import pickletools, glob, json

results = {}
for f in sorted(glob.glob('model_*.pkl')):
    data = open(f, 'rb').read()
    vals = {}
    prev_str = None
    for opcode, arg, pos in pickletools.genops(data):
        n = opcode.name
        if n in ('SHORT_BINUNICODE', 'BINUNICODE', 'UNICODE'):
            prev_str = arg
